pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }

    // fuzz the bytes4 value; the deciding value is the interface id to query
    function testFuzz_property(bytes4 iface) public {
        // Keep domain wide; no restrictive assumes so fuzzer can find the IAccessControl id
        // Query supportsInterface and ensure the reference contract returns true when
        // asked specifically about the IAccessControl interface id.
        // We compute the canonical IAccessControl id on-chain by constructing its ABI selector
        // using the known function signatures from the interface. The reference implementation
        // (correct C) should return true for that id; the mutant that always returns false will fail.

        // Build IAccessControl interface id by XOR-ing selectors of its external functions
        bytes4 id_hasRole = bytes4(keccak256("hasRole(bytes32,address)"));
        bytes4 id_getRoleAdmin = bytes4(keccak256("getRoleAdmin(bytes32)"));
        bytes4 id_grantRole = bytes4(keccak256("grantRole(bytes32,address)"));
        bytes4 id_revokeRole = bytes4(keccak256("revokeRole(bytes32,address)"));
        bytes4 id_renounceRole = bytes4(keccak256("renounceRole(bytes32,address)"));

        bytes4 ia = id_hasRole ^ id_getRoleAdmin ^ id_grantRole ^ id_revokeRole ^ id_renounceRole;

        // call supportsInterface and observe result (wrap in try/catch per rules)
        bool ok;
        try c.supportsInterface(ia) returns (bool r) {
            ok = r;
        } catch {
            ok = false;
        }

        // The single assertion: the reference contract must report true for IAccessControl's id
        assertTrue(ok);
    }
}

